* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 16px; background: #182b35; color: #f5f2df; }
body { min-height: 100vh; margin: 0; padding: 32px 18px 22px; display: grid; place-content: center; justify-items: center; gap: 20px; background-color: #182b35; background-image: linear-gradient(#ffffff08 1px, transparent 1px), linear-gradient(90deg, #ffffff08 1px, transparent 1px); background-size: 24px 24px; }
.thermostat { width: min(100%, 410px); padding: 30px; border: 3px solid #f5f2df; border-radius: 8px; background: #253e47; box-shadow: 8px 8px 0 #0f1b22; }
.header { text-align: center; }
.pixel-mark { display: block; width: 20px; height: 20px; margin: 0 auto 14px; background: #f2b84b; box-shadow: 8px 0 #f2b84b, 0 8px #f2b84b, 8px 8px #f2b84b; transform: translateX(-4px); }
.eyebrow, .readout-label, .readout-unit { margin: 0; color: #b9d1c6; font-size: .8rem; font-weight: 750; letter-spacing: .12em; }
h1 { margin: 6px 0 26px; font-size: clamp(1.45rem, 6vw, 1.8rem); line-height: 1.2; }
.room-readout { padding: 16px 12px; text-align: center; border: 2px solid #46636a; border-radius: 5px; background: #182b35; }
.room-temp { margin: 4px 0 0; color: #f2b84b; font-size: 3.25rem; font-weight: 800; line-height: 1.05; }
.unit { font-size: .62em; vertical-align: .35em; }
.readout-unit { display: block; margin-top: 3px; font-size: .7rem; }
.target-section { margin-top: 26px; }
.target-section > .readout-label, .mode-section > .readout-label { display: block; text-align: center; }
.target-control { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin: 10px 0 14px; }
.step-button { width: 52px; height: 52px; flex: 0 0 52px; border: 2px solid #f5f2df; border-radius: 4px; background: #35545c; color: #f5f2df; font: 700 1.8rem/1 system-ui, sans-serif; cursor: pointer; transition: background .15s, transform .15s, box-shadow .15s; }
.step-button:hover { background: #47717a; }
.step-button:active { transform: translateY(2px); box-shadow: inset 0 2px 0 #182b35; }
.step-button:focus-visible, select:focus-visible, .temperature-slider:focus-visible { outline: 3px solid #f2b84b; outline-offset: 3px; }
.target-temp { color: #f2b84b; font-size: clamp(2.8rem, 12vw, 3.5rem); font-weight: 800; font-variant-numeric: tabular-nums; line-height: 1; }
.temperature-slider { display: block; width: 100%; height: 24px; margin: 0; accent-color: #f2b84b; cursor: pointer; }
.range-labels { display: flex; justify-content: space-between; color: #b9d1c6; font-size: .8rem; }
.mode-section { margin-top: 24px; }
select { width: 100%; min-height: 48px; margin-top: 9px; padding: 0 14px; border: 2px solid #46636a; border-radius: 4px; background: #182b35; color: #f5f2df; font: inherit; font-weight: 650; cursor: pointer; }
select:hover { border-color: #b9d1c6; }
.status { display: flex; align-items: center; gap: 13px; margin-top: 24px; padding: 14px; border: 2px solid #46636a; border-radius: 4px; background: #182b35; }
.status-light { width: 12px; height: 12px; flex: 0 0 12px; border-radius: 50%; background: #f2b84b; box-shadow: 0 0 0 4px #f2b84b26; }
.status-copy { display: grid; gap: 2px; }
.status-copy .readout-label { font-size: .68rem; }
.status-copy strong { font-size: 1.1rem; }
.status-icon { margin-left: auto; color: #f2b84b; font-size: 1.5rem; font-weight: 800; }
.thermostat[data-state="cooling"] .status-light { background: #71c8bd; box-shadow: 0 0 0 4px #71c8bd26; }
.thermostat[data-state="cooling"] .status-icon { color: #71c8bd; }
.thermostat[data-state="idle"] .status-light { background: #b9d1c6; box-shadow: 0 0 0 4px #b9d1c626; }
.thermostat[data-state="idle"] .status-icon { color: #b9d1c6; }
.page-note { margin: 0; color: #b9d1c6; font-size: .9rem; text-align: center; }
@media (max-width: 400px) { body { padding: 20px 14px; } .thermostat { padding: 24px 20px; } }

const thermostat = document.querySelector('.thermostat');
const targetOutput = document.querySelector('#target');
const temperatureSlider = document.querySelector('#temperature');
const modeSelect = document.querySelector('#mode');
const statusText = document.querySelector('#status');
const statusIcon = document.querySelector('#status-icon');
const roomTemperature = 21;
let targetTemperature = 22;

function render() {
  targetOutput.innerHTML = `${targetTemperature.toFixed(1)}<span class="unit">°</span>`;
  temperatureSlider.value = targetTemperature;
  document.querySelector('#decrease').disabled = targetTemperature <= 10;
  document.querySelector('#increase').disabled = targetTemperature >= 30;

  let state = 'idle';
  if (modeSelect.value === 'heat' && targetTemperature > roomTemperature) state = 'heating';
  if (modeSelect.value === 'cool' && targetTemperature < roomTemperature) state = 'cooling';

  thermostat.dataset.state = state;
  statusText.textContent = state === 'idle' ? 'Idle' : state === 'heating' ? 'Heating' : 'Cooling';
  statusIcon.textContent = state === 'heating' ? '↑' : state === 'cooling' ? '↓' : '·';
}

function adjustTarget(amount) {
  targetTemperature = Math.min(30, Math.max(10, targetTemperature + amount));
  render();
}

document.querySelector('#decrease').addEventListener('click', () => adjustTarget(-0.5));
document.querySelector('#increase').addEventListener('click', () => adjustTarget(0.5));
temperatureSlider.addEventListener('input', () => {
  targetTemperature = Number(temperatureSlider.value);
  render();
});
modeSelect.addEventListener('change', render);
render();
